<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
const panel=ref<HTMLElement|null>(null),trigger=ref<HTMLButtonElement|null>(null),opened=ref(false),placement=ref('bottom'),notice=ref('No local acknowledgement yet.'),position=ref({left:'0px',top:'0px'})
async function locate(){await nextTick();if(!opened.value||!panel.value||!trigger.value)return;const a=trigger.value.getBoundingClientRect(),b=panel.value.getBoundingClientRect();let y=placement.value==='bottom'?a.bottom+8:a.top-b.height-8;if(y+b.height>innerHeight-12)y=a.top-b.height-8;if(y<12)y=a.bottom+8;position.value={left:`${Math.max(12,Math.min(a.left,innerWidth-b.width-12))}px`,top:`${Math.max(12,Math.min(y,innerHeight-b.height-12))}px`}}
function sync(e:Event){opened.value=(e as ToggleEvent).newState==='open';locate()}
function close(){panel.value?.hidePopover();trigger.value?.focus()}
function acknowledge(){notice.value='Sample note acknowledged locally. Nothing saved.';close()}
onMounted(()=>{window.addEventListener('resize',locate);window.addEventListener('scroll',locate,true)})
onBeforeUnmount(()=>{panel.value?.hidePopover();window.removeEventListener('resize',locate);window.removeEventListener('scroll',locate,true)})
</script>
<template><section class="popover-usage" aria-label="Popover usage demonstration"><label>Preferred placement<select v-model="placement" @change="locate"><option>bottom</option><option>top</option></select></label><p>Fictitious local sample. No account, payment or message changes.</p><div class="stage"><button ref="trigger" type="button" popovertarget="popover-guide-panel" aria-haspopup="dialog" :aria-expanded="opened" aria-controls="popover-guide-panel">Open sample note</button><section ref="panel" id="popover-guide-panel" popover="auto" role="dialog" aria-labelledby="popover-guide-title" :style="position" @toggle="sync"><header><h3 id="popover-guide-title">Sample workspace note</h3><button type="button" autofocus @click="close">Close note</button></header><p>This note is local only. Acknowledge does not save or contact anyone.</p><button type="button" @click="acknowledge">Acknowledge note</button></section></div><button type="button">Outside focus target</button><p role="status">{{notice}}</p></section></template>
<style scoped>
.popover-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.popover-usage label{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button,select{min-height:44px;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft);cursor:pointer}.stage{min-height:340px;display:flex;align-items:center;justify-content:center}[popover]{position:fixed;inset:auto;margin:0;width:min(340px,calc(100vw - 24px));max-height:calc(100dvh - 24px);box-sizing:border-box;overflow:auto;padding:18px;border:1px solid var(--vp-c-divider);border-radius:12px;background:var(--vp-c-bg-soft);color:var(--vp-c-text-1);box-shadow:0 12px 32px #0006}[popover]:popover-open{animation:popover-arrive 160ms ease-out}header{display:flex;gap:12px;align-items:start;justify-content:space-between}header h3{margin:0;font-size:18px}header button{flex-shrink:0}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:3px}@keyframes popover-arrive{from{opacity:0;translate:0 4px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){[popover]:popover-open{animation:none!important;translate:none}}
</style>
